-- Embedded 128x128 state icons for StreamRoute.

StreamRouteIcons = {
  DK = [[]],
  US = [[]],
}

local ICON_STORAGE_KEYS = {
  DK = "streamRouteFlagIconDkIdV1",
  US = "streamRouteFlagIconUsIdV1",
}

local CUSTOM_ICON_ID_MIN = 1000

local function iconBytes(hexValue)
  local hex = tostring(hexValue or ""):gsub("%s+", "")
  assert(#hex > 0 and #hex % 2 == 0 and hex:match("^%x+$"),
    "Embedded StreamRoute icon is invalid")

  local bytes = {}
  hex:gsub("(..)", function(pair)
    bytes[#bytes + 1] = string.char(tonumber(pair, 16))
  end)
  return table.concat(bytes)
end

local function readSelectedIcon(self)
  local selected = tonumber(self.properties and self.properties.deviceIcon)
  if api and api.get then
    local ok, device = pcall(api.get, "/devices/" .. tostring(self.id))
    if ok and type(device) == "table" and type(device.properties) == "table" then
      selected = tonumber(device.properties.deviceIcon) or selected
    end
  end
  return selected or 0
end

local function iconMode(mode)
  if tostring(mode or ""):upper() == "US" then return "US" end
  return "DK"
end

function QuickApp:selectStreamRouteIcon(iconId)
  local id = tonumber(iconId)
  if not id or id < CUSTOM_ICON_ID_MIN then return false, "invalid icon id" end
  if readSelectedIcon(self) == id then return true, id end

  local ok, errorMessage = pcall(api.put, "/devices/" .. tostring(self.id), {
    properties = { deviceIcon = id },
  })
  if not ok then return false, tostring(errorMessage) end

  if readSelectedIcon(self) ~= id then
    return false, "HC3 rejected icon id " .. tostring(id)
  end

  self.properties = self.properties or {}
  self.properties.deviceIcon = id
  return true, id
end

function QuickApp:updateStreamRouteIcon(mode)
  local desired = iconMode(mode)
  self.pendingStreamRouteIconMode = desired
  local ids = self.streamRouteIconIds or {}
  local id = tonumber(ids[desired])
  if not id then return false, "icon is not installed yet" end

  local selected, selectError = self:selectStreamRouteIcon(id)
  if not selected then
    self:warning("StreamRoute " .. desired
      .. " icon could not be selected: " .. tostring(selectError))
    return false, selectError
  end
  return true, id
end

function QuickApp:ensureStreamRouteIcons()
  self.streamRouteIconIds = self.streamRouteIconIds or {}

  for _, mode in ipairs({ "DK", "US" }) do
    local stored = tonumber(self:internalStorageGet(ICON_STORAGE_KEYS[mode]) or 0) or 0
    if stored >= CUSTOM_ICON_ID_MIN then
      self.streamRouteIconIds[mode] = stored
    end
  end

  if self.streamRouteIconIds.DK and self.streamRouteIconIds.US then
    if self.mode then self:updateStreamRouteIcon(self.mode) end
    return
  end

  if type(self.uploadIconFiles) ~= "function"
      or type(self.deviceIconTypeMapping) ~= "table" then
    self:warning("HC3 icon upload API is unavailable")
    return
  end

  local mapping = self.deviceIconTypeMapping[self.type]
  if type(mapping) ~= "table" or type(mapping.fileNames) ~= "table"
      or #mapping.fileNames ~= 1 then
    self:warning("Unexpected HC3 icon mapping for " .. tostring(self.type))
    return
  end

  local modes = { "DK", "US" }

  local function install(index)
    local mode = modes[index]
    if not mode then
      self:debug("StreamRoute flag icons ready: DK="
        .. tostring(self.streamRouteIconIds.DK)
        .. ", US=" .. tostring(self.streamRouteIconIds.US))
      if self.pendingStreamRouteIconMode or self.mode then
        self:updateStreamRouteIcon(self.pendingStreamRouteIconMode or self.mode)
      end
      return
    end

    if self.streamRouteIconIds[mode] then
      install(index + 1)
      return
    end

    self:uploadIconFiles({
      files = { iconBytes(StreamRouteIcons[mode]) },
      fileNames = mapping.fileNames,
      deviceType = self.type,
    }, {}, function(id)
      local numericId = tonumber(id)
      if not numericId or numericId < CUSTOM_ICON_ID_MIN then
        self:warning("StreamRoute " .. mode
          .. " icon upload returned invalid id " .. tostring(id))
        return
      end

      self.streamRouteIconIds[mode] = numericId
      self:internalStorageSet(ICON_STORAGE_KEYS[mode], tostring(numericId))
      self:debug("StreamRoute " .. mode
        .. " icon installed: deviceIcon=" .. tostring(numericId))
      install(index + 1)
    end, function(uploadError)
      self:warning("StreamRoute " .. mode
        .. " icon upload failed: " .. tostring(uploadError))
    end)
  end

  install(1)
end
